insert into public.destinations (
insert into public.safaris (slug, name, description, duration, highlights, image_url, image_alt, sort_order, translations) values
  ('kenya', 'Kenya', 'Golden savannahs, extraordinary wildlife and slow evenings under wide-open skies. Add a Nairobi stay if you’d like a little city energy.', '6–8 days', array['Masai Mara wildlife safari', 'Big Five experience', 'Optional Nairobi stay']::text[], 'https://framerusercontent.com/images/6SsI36c4HAR67C1wbKSyApsvFic.jpg', 'Kenya Safari', 0, '{"fr":{"name":"Kenya","description":"Savanes dorées, faune extraordinaire et soirées tranquilles sous un ciel immense. Ajoutez un séjour à Nairobi pour un peu d’énergie urbaine.","duration":"6 à 8 jours","highlights":["Safari dans le Masai Mara","Les Big Five","Séjour à Nairobi en option"],"imageAlt":"Safari au Kenya"},"ar":{"name":"كينيا","description":"سافانا ذهبية وحياة برية استثنائية وأمسيات هادئة تحت سماء واسعة. أضف إقامة في نيروبي إن أردت بعض حيوية المدينة.","duration":"من 6 إلى 8 أيام","highlights":["سفاري في ماساي مارا","تجربة الخمسة الكبار","إقامة اختيارية في نيروبي"],"imageAlt":"سفاري في كينيا"}}'::jsonb),
  ('tanzania', 'Tanzania', 'Follow the rhythm of the wild across the Serengeti and into Ngorongoro’s spectacular landscapes. An optional Zanzibar extension adds a softer landing.', '7–10 days', array['Serengeti safari', 'Ngorongoro Crater', 'Big Five experience']::text[], 'https://framerusercontent.com/images/XZnnrW7DcFPTTY3fNI61tGbCFxY.jpg', 'Tanzania Safari', 1, '{"fr":{"name":"Tanzanie","description":"Suivez le rythme de la vie sauvage à travers le Serengeti et dans les paysages spectaculaires du Ngorongoro. Une extension à Zanzibar en option pour finir en douceur.","duration":"7 à 10 jours","highlights":["Safari dans le Serengeti","Cratère du Ngorongoro","Les Big Five"],"imageAlt":"Safari en Tanzanie"},"ar":{"name":"تنزانيا","description":"تابع إيقاع البرية عبر سيرينغيتي وصولًا إلى مناظر نغورونغورو المذهلة. وامتداد اختياري إلى زنجبار لختام أهدأ.","duration":"من 7 إلى 10 أيام","highlights":["سفاري في سيرينغيتي","فوهة نغورونغورو","تجربة الخمسة الكبار"],"imageAlt":"سفاري في تنزانيا"}}'::jsonb),
  ('south-africa', 'South Africa', 'Wildlife-filled days and a fresh sense of freedom in Kruger. Extend your adventure to Cape Town for coastal scenery and a completely different pace.', '7–10 days', array['Kruger National Park', 'Immersive safari experience', 'Optional Cape Town extension']::text[], 'https://framerusercontent.com/images/l6UT91V9Fyoy0nxbUmbY6r0vAc.jpg', 'South Africa Safari', 2, '{"fr":{"name":"Afrique du Sud","description":"Des journées riches en faune et un vrai sentiment de liberté à Kruger. Prolongez l’aventure au Cap pour des paysages côtiers et un tout autre rythme.","duration":"7 à 10 jours","highlights":["Parc national Kruger","Safari en immersion","Extension au Cap en option"],"imageAlt":"Safari en Afrique du Sud"},"ar":{"name":"جنوب أفريقيا","description":"أيام مليئة بالحياة البرية وإحساس جديد بالحرية في كروغر. مدّد مغامرتك إلى كيب تاون لمناظر ساحلية وإيقاع مختلف تمامًا.","duration":"من 7 إلى 10 أيام","highlights":["حديقة كروغر الوطنية","تجربة سفاري غامرة","امتداد اختياري إلى كيب تاون"],"imageAlt":"سفاري في جنوب أفريقيا"}}'::jsonb),
  ('kenya-zanzibar', 'Kenya + Zanzibar', 'A little wild, a little barefoot. Pair Kenya’s unforgettable wildlife with turquoise-water days on Zanzibar’s tropical shores.', '10–14 days', array['Safari + tropical beach', 'Masai Mara experience', 'Zanzibar relaxation']::text[], 'https://framerusercontent.com/images/uJRZAFdL7qhA5KTUA6Ec3MgE9E.jpg', 'Kenya + Zanzibar Safari', 3, '{"fr":{"name":"Kenya + Zanzibar","description":"Un peu sauvage, un peu pieds nus. Associez la faune inoubliable du Kenya à des journées eaux turquoise sur les plages tropicales de Zanzibar.","duration":"10 à 14 jours","highlights":["Safari + plage tropicale","Expérience Masai Mara","Détente à Zanzibar"],"imageAlt":"Safari Kenya + Zanzibar"},"ar":{"name":"كينيا + زنجبار","description":"قليل من البرية وقليل من الحفاء. اجمع بين الحياة البرية التي لا تُنسى في كينيا وأيام المياه الفيروزية على شواطئ زنجبار الاستوائية.","duration":"من 10 إلى 14 يومًا","highlights":["سفاري + شاطئ استوائي","تجربة ماساي مارا","استرخاء في زنجبار"],"imageAlt":"سفاري كينيا + زنجبار"}}'::jsonb),
  ('tanzania-zanzibar', 'Tanzania + Zanzibar', 'From the Serengeti’s vast horizons to warm Indian Ocean breezes. Your wildlife adventure, finished with time to switch off by the sea.', '10–14 days', array['Serengeti safari', 'Wildlife experience', 'Zanzibar beach extension']::text[], 'https://framerusercontent.com/images/27xKKdXjS70DQEG2GWcBACV7Lx0.jpg', 'Tanzania + Zanzibar Safari', 4, '{"fr":{"name":"Tanzanie + Zanzibar","description":"Des vastes horizons du Serengeti aux brises chaudes de l’océan Indien. Votre aventure sauvage, terminée par du temps pour déconnecter au bord de la mer.","duration":"10 à 14 jours","highlights":["Safari dans le Serengeti","Expérience de la vie sauvage","Extension plage à Zanzibar"],"imageAlt":"Safari Tanzanie + Zanzibar"},"ar":{"name":"تنزانيا + زنجبار","description":"من آفاق سيرينغيتي الواسعة إلى نسائم المحيط الهندي الدافئة. مغامرتك البرية تُختتم بوقت للاسترخاء على شاطئ البحر.","duration":"من 10 إلى 14 يومًا","highlights":["سفاري في سيرينغيتي","تجربة الحياة البرية","امتداد شاطئي في زنجبار"],"imageAlt":"سفاري تنزانيا + زنجبار"}}'::jsonb)
insert into public.services (slug, name, country, flag, price_dt, description, includes, documents, sort_order, translations) values
  ('thailand-visa', 'Thailand Visa Assistance', 'Thailand', '🇹🇭', 55, '', array['Document checklist', 'Document review', 'Application preparation / guidance', 'SAFRA support']::text[], array['Passport copy', 'Personal photo', 'Flight / travel details', 'Accommodation details', 'Bank statement / financial proof', 'Employment / business documents if required']::text[], 0, '{"fr":{"name":"Assistance visa Thaïlande","country":"Thaïlande","includes":["Liste des documents","Vérification des documents","Préparation / accompagnement de la demande","Suivi SAFRA"],"documents":["Copie du passeport","Photo d’identité","Détails du vol / du voyage","Détails de l’hébergement","Relevé bancaire / justificatif financier","Documents professionnels si nécessaire"]},"ar":{"name":"المساعدة في تأشيرة تايلاند","country":"تايلاند","includes":["قائمة الوثائق","مراجعة الوثائق","تحضير الطلب / الإرشاد","متابعة سفرة"],"documents":["نسخة من جواز السفر","صورة شخصية","تفاصيل الطيران / الرحلة","تفاصيل الإقامة","كشف حساب بنكي / إثبات مالي","وثائق العمل أو النشاط عند الحاجة"]}}'::jsonb)
insert into public.packs (slug, title, country, route, blurb, price_dt, nights, image_url, includes, vibes, destination_slug, translations, sort_order) values
  ('cairo-weekend', 'Cairo long weekend', 'Egypt', 'Cairo · Giza', 'The pyramids, the old souks and the Nile at night, in four easy days.', 1490, 4, 'https://framerusercontent.com/images/EdMMpeTsjEBWluFXZ2r0bI5Xxo.jpg', array['flights', 'hotel', 'breakfast', 'transfers', 'visa', 'plan']::text[], array['Culture', 'City']::text[], 'egypt', '{"fr":{"title":"Long week-end au Caire","country":"Égypte","route":"Le Caire · Gizeh","blurb":"Les pyramides, les vieux souks et le Nil la nuit, en quatre jours tranquilles."},"ar":{"title":"عطلة طويلة في القاهرة","country":"مصر","route":"القاهرة · الجيزة","blurb":"الأهرامات والأسواق القديمة والنيل ليلًا، في أربعة أيام مريحة."}}'::jsonb, 0),
  ('nile-classic', 'Cairo & the Nile', 'Egypt', 'Cairo · Luxor · Aswan', 'Temples by day, a felucca at sunset, and the train down the Nile.', 2390, 7, 'https://images.unsplash.com/photo-1771325676184-44d8035e3cd1?w=1400&q=85', array['flights', 'hotel', 'breakfast', 'transfers', 'activities', 'visa', 'plan']::text[], array['Culture', 'Adventure']::text[], 'egypt', '{"fr":{"title":"Le Caire et le Nil","country":"Égypte","route":"Le Caire · Louxor · Assouan","blurb":"Des temples le jour, une felouque au coucher du soleil et le train le long du Nil."},"ar":{"title":"القاهرة والنيل","country":"مصر","route":"القاهرة · الأقصر · أسوان","blurb":"معابد في النهار، فلوكة عند الغروب، والقطار على طول النيل."}}'::jsonb, 1),
  ('cappadocia-istanbul', 'Istanbul & Cappadocia', 'Türkiye', 'Istanbul · Göreme', 'Bosphorus evenings, then a sunrise among the balloons.', 2890, 6, 'https://framerusercontent.com/images/g7qTJCUK0HIbl4Od1pOA1so1eg.jpg', array['flights', 'hotel', 'breakfast', 'transfers', 'activities', 'plan']::text[], array['Culture', 'Food', 'City']::text[], 'turkiye', '{"fr":{"title":"Istanbul et la Cappadoce","country":"Turquie","route":"Istanbul · Göreme","blurb":"Des soirées sur le Bosphore, puis un lever de soleil parmi les montgolfières."},"ar":{"title":"إسطنبول وكابادوكيا","country":"تركيا","route":"إسطنبول · غوريمه","blurb":"أمسيات على البوسفور، ثم شروق الشمس بين المناطيد."}}'::jsonb, 2),
  ('bangkok-krabi', 'Bangkok & Krabi', 'Thailand', 'Bangkok · Ao Nang', 'Street food and rooftops first, then limestone cliffs and island days.', 4290, 9, 'https://framerusercontent.com/images/snHq8305shuNdUjeU5oyWBUIZw.jpg', array['flights', 'hotel', 'breakfast', 'transfers', 'activities', 'visa', 'plan']::text[], array['Beach', 'Nightlife', 'Food']::text[], 'thailand', '{"fr":{"title":"Bangkok et Krabi","country":"Thaïlande","route":"Bangkok · Ao Nang","blurb":"Street food et rooftops d’abord, puis falaises calcaires et journées sur les îles."},"ar":{"title":"بانكوك وكرابي","country":"تايلاند","route":"بانكوك · آو نانغ","blurb":"أكل الشارع والأسطح أولًا، ثم المنحدرات الصخرية وأيام الجزر."}}'::jsonb, 3),
  ('thai-islands', 'Thai islands, slowly', 'Thailand', 'Phuket · Phi Phi · Krabi', 'Three islands, beachfront rooms and a private longtail day.', 7490, 11, 'https://framerusercontent.com/images/GL4tcr2qJCc1BJINLyIiLL1ySA.jpg', array['flights', 'hotel', 'breakfast', 'transfers', 'activities', 'visa', 'plan']::text[], array['Beach', 'Luxury', 'Nature']::text[], 'thailand', '{"fr":{"title":"Les îles thaïes, en douceur","country":"Thaïlande","route":"Phuket · Phi Phi · Krabi","blurb":"Trois îles, des chambres face à la mer et une journée en longtail privé."},"ar":{"title":"جزر تايلاند على مهل","country":"تايلاند","route":"بوكيت · في في · كرابي","blurb":"ثلاث جزر، غرف على الشاطئ، ويوم كامل بقارب خاص."}}'::jsonb, 4)
